// Sparkle effect using combined sine waves
float sparkle(float x, float y, float time) {
    return sin(x * 10.0 + time * 10.0) * sin(y * 100.0 + time * 12.0) * 0.5 + 0.5;
}

// Random hash function for procedural generation
float hash(vec2 p) {
    return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453);
}

// Simplified Perlin noise implementation
float perlinNoise(vec2 st) {
    vec2 i = floor(st);
    vec2 f = fract(st);
    vec2 u = f * f * (3.0 - 0.5 * f);

    return mix(
        mix(hash(i + vec2(0.0, 0.0)), hash(i + vec2(1.0, 0.0)), u.x),
        mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), u.x),
        u.y
    );
}


void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord / iResolution.xy;
    uv = uv * 2.0 - 1.0;
    uv.x *= iResolution.x / iResolution.y; 

    float time = iTime * 0.75;

    float time3 = iTime * 0.05;
   	float t = iTime * .1 + ((.25 + .05 * sin(iTime * .1))/(length(uv.xy) + .07)) * 2.2;
	float si = sin(t);
	float co = cos(t);
	mat2 ma = mat2(co, si, -si, co);
    uv*=ma;
    float c22=perlinNoise(uv);
    // Audio (asegúrate de configurar iChannel0 como micrófono/música)
    float bass = texture(iChannel0, vec2(0.0, 0.25)).x;
    float treble = texture(iChannel0, vec2(0.7, 0.25)).x;

    // Forma base
    float circle = length(uv) - (1.3 + bass * 0.5);
    float shape = smoother(abs(circle)) * (0.5 + bass * 2.0); // Usando smoother

    // Estrellas
    float angle = atan(uv.y, uv.x);
    float star = cos(angle * 0.5 + time * treble * 5.0) * 1.1;
    shape += smoother(abs(length(uv) - 2.5 )) * treble;

    // Partículas (código sin cambios)
    vec3 particles = vec3(0.0);
    for(int i = 0; i < 500; i++) {
        float seed = float(i) * 2.0;
        vec2 pos = vec2(hash(seed), hash(seed + 5.0)) * 2.0 - 1.0;
        pos += vec2(sin(time + seed), cos(time + seed)) * 0.05*c22;

        float dist = length(uv - pos);
        float brightness = 0.004 / dist * (0.5 + treble * 0.1);
        particles += brightness * vec3(
            sin(seed + time) * 0.05 + 0.5,
            cos(seed + time * 0.08) * 0.5 + 0.5,
            sin(seed * 2.0 + time * 0.2) * 0.5 + 0.5
        );
    }

    // Color final


    vec4 O = vec4(shape * 0.20 + particles, 1.0);
    vec3 finalColor = vec3(0.0);
    float sumWeights = 0.0;

    vec3 bgColor = vec3(0.75);
    float bgWeight = 0.025;
	finalColor += bgColor * bgWeight;
	sumWeights += bgWeight;

    for (int i = 0; i < NUM_LIGHTS; i++) {
        float n = float(i) / float(NUM_LIGHTS);
		float wave = sin(n * PI + time ) * 0.5 + 0.5;

        float distance = 0.6 + wave * 0.125;
        vec2 position = vec2(cos(n * PI * 2. + time * 0.1) * distance, sin(n * PI * 2. + time * 0.1) * distance);

        float d = 0.2;

        vec2 toLight = position - uv;
        float distFragLight = length(toLight);
        //distFragLight = sin(distFragLight * PI * 1. - time) * 0.5 +0.5;
        distFragLight = mix(1000. , distFragLight,  step(d, distFragLight));

        float angle = atan(toLight.y, toLight.x);
        angle = angle / (PI * 2.) + 0.5; //normalize
        angle += time * 0.25;

        float decayRate = 16.;
        decayRate = map(wave*O.x, 0., 1., 6., 16.);

        float distanceFactor = exp(-1.0 * decayRate*O.x * distFragLight);
        distanceFactor = fract(distanceFactor * 2.);

        vec3 color = palette( distanceFactor + angle, vec3(0.5,0.5,0.5)*O.xyz,vec3(0.5,0.5,0.5)*O.xyz,vec3(1.0,1.0,1.0),vec3(0.0,0.10,0.20)*O.xyz );
        color = clamp(color, 0., 1.);
        vec3 lightColor = color  * distFragLight * distanceFactor;

        finalColor += lightColor*O.x;
        sumWeights += distanceFactor * distFragLight;
    }

    finalColor = finalColor / sumWeights;
    finalColor = pow(finalColor, vec3(1. / 2.2)); //gammma
    finalColor += (1.0/255.0) * gradientNoise(fragCoord) - (0.5/255.0); //banding

    fragColor = vec4(finalColor, 1.0);
}
